        uk: 'Скажи продавцю, у чому проблема. «It does not fit» — це не підходить за розміром. «It does not work» — воно не працює. «It is too big» — надто велике. «I do not have a receipt» — у мене немає чека.',
        es: 'Dile al vendedor cuál es el problema. «It does not fit» — no me queda bien. «It does not work» — no funciona. «It is too big» — es demasiado grande. «I do not have a receipt» — no tengo el recibo.',
