        uk: 'Can I have...? — це готова формула для будь-якого прохання. Can — «чи можу я», have — «отримати». Разом вони звучать м\'яко й природно в будь-якому кафе світу.',
        es: 'Can I have...? es una fórmula lista para cualquier petición. Can significa «¿puedo?» y have significa «tener». Juntas suenan suaves y naturales en cualquier café del mundo.',
